const repo = ($env.GITHUB_REPO || '').trim();
const githubToken = ($env.GITHUB_TOKEN || '').trim();
const anthropicApiKey = ($env.ANTHROPIC_API_KEY || '').trim();
const slackWebhookUrl = ($env.SLACK_WEBHOOK_URL || '').trim();
const discordWebhookUrl = ($env.DISCORD_WEBHOOK_URL || '').trim();
const webhookUrl = slackWebhookUrl || discordWebhookUrl;
const deliveryPlatform = ($env.DELIVERY_PLATFORM || (slackWebhookUrl ? 'slack' : 'discord')).toLowerCase();
const language = (($env.LANGUAGE || 'EN').trim().toUpperCase() === 'FR') ? 'FR' : 'EN';
const model = ($env.ANTHROPIC_MODEL || 'claude-sonnet-4-20250514').trim();
const missing = [];

if (!repo) missing.push('GITHUB_REPO');
if (!githubToken) missing.push('GITHUB_TOKEN');
if (!anthropicApiKey) missing.push('ANTHROPIC_API_KEY');
if (!webhookUrl) missing.push('SLACK_WEBHOOK_URL or DISCORD_WEBHOOK_URL');

const [owner = '', repoName = ''] = repo.split('/');
const until = new Date();
const since = new Date(until);
since.setDate(since.getDate() - 7);

return [
  {
    json: {
      repo,
      owner,
      repoName,
      githubToken,
      anthropicApiKey,
      webhookUrl,
      deliveryPlatform,
      language,
      model,
      sinceIso: since.toISOString(),
      untilIso: until.toISOString(),
      sinceDate: since.toISOString().slice(0, 10),
      untilDate: until.toISOString().slice(0, 10),
      missingConfig: missing.join(', '),
      hasMissingConfig: missing.length > 0,
      destinationLabel: $env.DESTINATION_CHANNEL || 'Slack/Discord channel'
    }
  }
];

const { owner, repoName, repo, githubToken, sinceIso, untilIso, sinceDate, untilDate } = $json;
const headers = {
  Authorization: `Bearer ${githubToken}`,
  Accept: 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28'
};

async function githubGet(url, label) {
  try {
    return await this.helpers.httpRequest({
      url,
      method: 'GET',
      headers,
      json: true,
      returnFullResponse: true,
      timeout: 120000
    });
  } catch (error) {
    const statusCode = error?.statusCode || error?.response?.statusCode || error?.cause?.statusCode;
    if (statusCode === 403 || statusCode === 429) {
      throw new Error(`GitHub rate limit or permission issue while fetching ${label}. Check token scopes and retry after the reset window.`);
    }
    throw new Error(`GitHub request failed for ${label}: ${error.message || error}`);
  }
}

const commitsUrl = `https://api.github.com/repos/${owner}/${repoName}/commits?since=${encodeURIComponent(sinceIso)}&until=${encodeURIComponent(untilIso)}&per_page=100`;
const issuesUrl = `https://api.github.com/search/issues?q=${encodeURIComponent(`repo:${repo} is:issue is:closed closed:${sinceDate}..${untilDate}`)}&per_page=100`;
const prsUrl = `https://api.github.com/search/issues?q=${encodeURIComponent(`repo:${repo} is:pr is:merged merged:${sinceDate}..${untilDate}`)}&per_page=100`;

const [commitsRes, issuesRes, prsRes] = await Promise.all([
  githubGet.call(this, commitsUrl, 'commits'),
  githubGet.call(this, issuesUrl, 'closed issues'),
  githubGet.call(this, prsUrl, 'merged PRs')
]);

const commits = Array.isArray(commitsRes.body) ? commitsRes.body.map((commit) => ({
  sha: String(commit.sha || '').slice(0, 7),
  message: commit?.commit?.message?.split('\n')[0] || '(no message)',
  author: commit?.commit?.author?.name || commit?.author?.login || 'unknown',
  date: commit?.commit?.author?.date || commit?.commit?.committer?.date || null,
  url: commit.html_url || ''
})) : [];

const closedIssues = Array.isArray(issuesRes.body?.items) ? issuesRes.body.items.map((item) => ({
  number: item.number,
  title: item.title,
  url: item.html_url,
  closedAt: item.closed_at || null
})) : [];

const mergedPrs = Array.isArray(prsRes.body?.items) ? prsRes.body.items.map((item) => ({
  number: item.number,
  title: item.title,
  url: item.html_url,
  closedAt: item.closed_at || null
})) : [];

return [
  {
    json: {
      ...$json,
      githubActivity: {
        commits,
        closedIssues,
        mergedPrs,
        counts: {
          commits: commits.length,
          closedIssues: closedIssues.length,
          mergedPrs: mergedPrs.length
        }
      }
    }
  }
];

const { language, repo, sinceDate, untilDate, githubActivity } = $json;
const counts = githubActivity.counts;
const commits = githubActivity.commits.slice(0, 8);
const closedIssues = githubActivity.closedIssues.slice(0, 8);
const mergedPrs = githubActivity.mergedPrs.slice(0, 8);

const intro = language === 'FR'
  ? `Tu rédiges un résumé hebdomadaire en Markdown pour le dépôt ${repo}. La période couvre du ${sinceDate} au ${untilDate}.`
  : `You are writing a weekly Markdown summary for the repository ${repo}. The reporting window runs from ${sinceDate} through ${untilDate}.`;

const rules = language === 'FR'
  ? [
      'Reste concis, clair et orienté vers l action.',
      'Mentionne les totaux pour les commits, issues fermées et PR fusionnées.',
      'Ajoute une section Points saillants, une section Risques ou blocages, et une section Prochaines étapes.',
      'Si les données sont faibles, le note honnêtement sans inventer.'
    ].join(' ')
  : [
      'Keep the tone concise, clear, and action-oriented.',
      'Mention totals for commits, closed issues, and merged PRs.',
      'Include a Highlights section, a Risks or Blockers section, and a Next Steps section.',
      'If the week is quiet, say so honestly without inventing activity.'
    ].join(' ');

const bullets = [
  language === 'FR' ? `Commits: ${counts.commits}` : `Commits: ${counts.commits}`,
  language === 'FR' ? `Issues fermées: ${counts.closedIssues}` : `Closed issues: ${counts.closedIssues}`,
  language === 'FR' ? `PR fusionnées: ${counts.mergedPrs}` : `Merged PRs: ${counts.mergedPrs}`,
  '',
  language === 'FR' ? 'Derniers commits:' : 'Recent commits:',
  ...commits.map((commit) => `- ${commit.sha} ${commit.message} (${commit.author})`),
  '',
  language === 'FR' ? 'Issues fermées:' : 'Closed issues:',
  ...closedIssues.map((issue) => `- #${issue.number} ${issue.title}`),
  '',
  language === 'FR' ? 'PR fusionnées:' : 'Merged PRs:',
  ...mergedPrs.map((pr) => `- #${pr.number} ${pr.title}`)
].join('\n');

return [
  {
    json: {
      ...$json,
      claudePrompt: `${intro}\n\n${rules}\n\n${bullets}`,
      claudeSystemPrompt: language === 'FR'
        ? 'Tu es un analyste de livraison technique. Écris en Markdown propre, avec des puces courtes et des titres simples.'
        : 'You are a technical delivery analyst. Write clean Markdown with short bullets and simple headings.'
    }
  }
];

const { anthropicApiKey, model, claudePrompt, claudeSystemPrompt } = $json;

try {
  const response = await this.helpers.httpRequest({
    url: 'https://api.anthropic.com/v1/messages',
    method: 'POST',
    headers: {
      'x-api-key': anthropicApiKey,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json'
    },
    body: {
      model,
      max_tokens: 1200,
      temperature: 0.3,
      system: claudeSystemPrompt,
      messages: [
        {
          role: 'user',
          content: claudePrompt
        }
      ]
    },
    json: true,
    returnFullResponse: true,
    timeout: 120000
  });

  const text = Array.isArray(response.body?.content)
    ? response.body.content.map((part) => part?.text || '').join('').trim()
    : '';

  if (!text) {
    throw new Error('Anthropic response did not include summary text.');
  }

  return [
    {
      json: {
        ...$json,
        summaryMarkdown: text,
        anthropicResponseId: response.body?.id || '',
        summaryWordCount: text.split(/\s+/).filter(Boolean).length
      }
    }
  ];
} catch (error) {
  const statusCode = error?.statusCode || error?.response?.statusCode || error?.cause?.statusCode;
  if (statusCode === 401) {
    throw new Error('Anthropic rejected the API key. Check ANTHROPIC_API_KEY.');
  }
  throw new Error(`Claude summary generation failed: ${error.message || error}`);
}

const { repo, language, deliveryPlatform, destinationLabel, summaryMarkdown, githubActivity, sinceDate, untilDate } = $json;
const intro = language === 'FR'
  ? `Résumé hebdomadaire pour ${repo} (${sinceDate} → ${untilDate})`
  : `Weekly summary for ${repo} (${sinceDate} → ${untilDate})`;

const header = [
  intro,
  language === 'FR'
    ? `Commits: ${githubActivity.counts.commits} | Issues fermées: ${githubActivity.counts.closedIssues} | PR fusionnées: ${githubActivity.counts.mergedPrs}`
    : `Commits: ${githubActivity.counts.commits} | Closed issues: ${githubActivity.counts.closedIssues} | Merged PRs: ${githubActivity.counts.mergedPrs}`,
  `Destination: ${destinationLabel}`
].join('\n');

const payloadText = `${header}\n\n${summaryMarkdown}`;
const webhookPayload = deliveryPlatform === 'discord'
  ? { content: payloadText }
  : { text: payloadText };

return [
  {
    json: {
      ...$json,
      payloadText,
      webhookPayload
    }
  }
];

const { webhookUrl, webhookPayload, deliveryPlatform } = $json;

try {
  const response = await this.helpers.httpRequest({
    url: webhookUrl,
    method: 'POST',
    body: webhookPayload,
    json: true,
    returnFullResponse: true,
    timeout: 120000
  });

  return [
    {
      json: {
        ...$json,
        deliveryStatus: response.statusCode || 200,
        deliveredTo: deliveryPlatform
      }
    }
  ];
} catch (error) {
  throw new Error(`Webhook delivery failed: ${error.message || error}`);
}
